<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>롯데월드타워 설계 시각화 - Qwen3-32b</title>
  <style>
    * {
      box-sizing: border-box;
    }
    body {
      margin: 0;
      font-family: sans-serif;
      background-color: #f5f5f5;
      color: #333;
    }
    #info {
      padding: 10px;
      background-color: #fff;
      border-bottom: 1px solid #ccc;
      text-align: center;
      font-weight: bold;
    }
    #controls {
      display: flex;
      justify-content: center;
      background-color: #fff;
      padding: 10px;
      border-bottom: 1px solid #ccc;
    }
    #controls button {
      margin: 0 5px;
      padding: 5px 10px;
      font-size: 14px;
      cursor: pointer;
    }
    #container {
      position: relative;
      width: 100%;
      height: 100vh;
    }
    #canvas {
      width: 100%;
      height: 100%;
    }
    #overlay {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      pointer-events: none;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 1.5em;
      font-weight: bold;
      background-color: rgba(0, 0, 0, 0.5);
      display: none;
    }
  </style>
</head>
<body>
  <div id="info">롯데월드타워 설계 시각화 - Qwen3-32b</div>
  <div id="controls">
    <button onclick="showDesignStep(0)">초기 설계</button>
    <button onclick="showDesignStep(1)">중간 설계</button>
    <button onclick="showDesignStep(2)">최종 설계</button>
    <button onclick="showFinalModel()">완성 모델</button>
  </div>
  <div id="container">
    <canvas id="canvas"></canvas>
    <div id="overlay">로딩 중...</div>
  </div>

  <script>
    const info = document.getElementById('info');
    const overlay = document.getElementById('overlay');

    const towerHeight = 555; // m
    const floors = 123;
    const baseWidth = 60; // m
    const topWidth = 20; // m

    let currentStep = 0;
    let camera, scene, renderer, modelGroup, controls;

    const steps = [
      {
        name: "초기 설계",
        description: "기본 타워 형태와 높이 설정. 한국 도자기의 선을 반영한 형태 시작.",
        scale: 0.5
      },
      {
        name: "중간 설계",
        description: "기초와 구조 개념 확정. 외곽선의 수축 비율 조정.",
        scale: 0.7
      },
      {
        name: "최종 설계",
        description: "최종 형태 확정. 외관 디자인 완성.",
        scale: 1.0
      }
    ];

    const finalModel = {
      name: "완성 모델",
      description: "롯데월드타워 실제 형태. 555m, 123층, 외곽 수축 형태.",
      scale: 1.0
    };

    function init() {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0xffffff);

      camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
      camera.position.set(100, 100, 100);

      renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('canvas') });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(window.devicePixelRatio);

      controls = new THREE.OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.05;
      controls.enablePan = false;

      window.addEventListener('resize', onWindowResize, false);

      overlay.style.display = 'block';
      overlay.textContent = '로딩 중...';

      setTimeout(() => {
        createTowerModel();
        animate();
        overlay.style.display = 'none';
      }, 500);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    }

    function createTowerModel() {
      scene.clear();

      const geometry = new THREE.CylinderGeometry(baseWidth, topWidth, towerHeight, 32, 32, true);
      const material = new THREE.MeshStandardMaterial({ color: 0x888888 });
      modelGroup = new THREE.Group();
      const mesh = new THREE.Mesh(geometry, material);
      mesh.rotation.x = -Math.PI / 2;
      modelGroup.add(mesh);
      scene.add(modelGroup);

      const light = new THREE.DirectionalLight(0xffffff, 1);
      light.position.set(10, 20, 10);
      scene.add(light);

      const ambient = new THREE.AmbientLight(0x444444);
      scene.add(ambient);
    }

    function showDesignStep(stepIndex) {
      currentStep = stepIndex;
      const step = steps[stepIndex];
      const scale = step.scale;
      modelGroup.scale.set(scale, scale, scale);
      info.textContent = `${step.name} - ${step.description}`;
    }

    function showFinalModel() {
      const step = finalModel;
      modelGroup.scale.set(step.scale, step.scale, step.scale);
      info.textContent = `${step.name} - ${step.description}`;
    }

    function animate() {
      requestAnimationFrame(animate);
      controls.update();
      renderer.render(scene, camera);
    }

    init();
  </script>
</body>
</html>
